UNLOCK TABLES;

--
-- Table structure for table `wp_posts`
--

DROP TABLE IF EXISTS `wp_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_posts` (
  `ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint unsigned NOT NULL DEFAULT '0',
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_title` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_excerpt` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `post_password` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `post_name` varchar(200) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `to_ping` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `pinged` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_parent` bigint unsigned NOT NULL DEFAULT '0',
  `guid` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `menu_order` int NOT NULL DEFAULT '0',
  `post_type` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `comment_count` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wp_posts`
--

LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (1,1,'2026-09-30 08:49:40','2026-09-30 08:49:40','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2026-09-30 08:49:40','2026-09-30 08:49:40','',0,'http://localhost/ukm-toko/?p=1',0,'post','',1),(2,1,'2026-09-30 08:49:40','2026-09-30 08:49:40','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://localhost/ukm-toko/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2026-09-30 08:49:40','2026-09-30 08:49:40','',0,'http://localhost/ukm-toko/?page_id=2',0,'page','',0),(3,1,'2026-09-30 08:49:40','2026-09-30 08:49:40','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost/ukm-toko.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2026-09-30 08:49:40','2026-09-30 08:49:40','',0,'http://localhost/ukm-toko/?page_id=3',0,'page','',0),(4,1,'2026-09-30 09:18:40','2026-09-30 09:18:40','<!-- Section Hero Banner -->\n<div class=\"ukm-hero-wrapper\" style=\"background: linear-gradient(rgba(15, 23, 42, 0.75), rgba(15, 23, 42, 0.85)), url(\'/wp-content/uploads/2026/10/bekgron.jpg\') center / cover no-repeat;\">\n<div class=\"ukm-hero-content\"><span class=\"ukm-badge\">Pusat Sembako &amp; Kebutuhan Pokok</span>\n<h1 class=\"ukm-hero-title\">Belanja Sembako Murah, Lengkap, dan Terpercaya</h1>\n<p class=\"ukm-hero-desc\">Menyediakan berbagai kebutuhan pokok rumah tangga, warung makan, dan toko kelontong dengan jaminan mutu terbaik dan harga grosir bersahabat.</p>\n\n<div class=\"ukm-btn-group\"><a class=\"ukm-btn ukm-btn-primary\" href=\"/shop/\">Lihat Katalog Toko</a>\n<a class=\"ukm-btn ukm-btn-outline\" href=\"/product-category/sembako/\">Kategori Sembako</a></div>\n</div>\n</div>\n<!-- Section Kategori Pilihan -->\n<div class=\"ukm-section\">\n<div class=\"ukm-section-header\">\n<h2 class=\"ukm-section-title\">Kategori Produk Unggulan</h2>\n<p class=\"ukm-section-subtitle\">Pilih kelompok produk sesuai kebutuhan belanja harian atau usaha Anda</p>\n\n</div>\n<div class=\"ukm-category-grid\"><a class=\"ukm-cat-card\" style=\"color: #000000; text-decoration: none;\" href=\"/product-category/sembako/\"><span class=\"ukm-cat-link\"><img class=\"size-medium wp-image-107 aligncenter\" src=\"http://localhost:8080/wp-content/uploads/2026/10/cat1-300x200.jpg\" alt=\"\" width=\"300\" height=\"200\" /></span></a><a class=\"ukm-cat-card\" href=\"/product-category/sembako/\">\n<span class=\"ukm-cat-tag\">Kategori 01</span>\n<span class=\"ukm-cat-title\">Sembako</span>\n<span class=\"ukm-cat-desc\">Beras, Minyak Goreng, Gula Pasir, dan Tepung Terigu</span>\n<span class=\"ukm-cat-link\">Belanja Sembako →</span>\n</a>\n<a class=\"ukm-cat-card\" href=\"/product-category/kebersihan/\">\n<span class=\"ukm-cat-tag\">Kategori 02</span>\n<span class=\"ukm-cat-title\">Kebersihan</span>\n<span class=\"ukm-cat-desc\">Sabun Cuci, Deterjen, dan Perlengkapan Sanitasi Rumah</span>\n<span class=\"ukm-cat-link\">Belanja Kebersihan →</span>\n</a>\n<a class=\"ukm-cat-card\" href=\"/product-category/minuman/\">\n<span class=\"ukm-cat-tag\">Kategori 03</span>\n<span class=\"ukm-cat-title\">Minuman</span>\n<span class=\"ukm-cat-desc\">Air Mineral, Kopi, Teh, dan Susu Kemasan Berkualitas</span>\n<span class=\"ukm-cat-link\">Belanja Minuman →</span>\n</a>\n<a class=\"ukm-cat-card\" href=\"/product-category/snack/\">\n<span class=\"ukm-cat-tag\">Kategori 04</span>\n<span class=\"ukm-cat-title\">Snack</span>\n<span class=\"ukm-cat-desc\">Aneka Biskuit, Keripik, dan Makanan Ringan Populer</span>\n<span class=\"ukm-cat-link\">Belanja Snack →</span>\n</a></div>\n</div>\n<!-- Section Produk Unggulan (WooCommerce Grid) -->\n<div class=\"ukm-section\">\n<div class=\"ukm-section-header\">\n<h2 class=\"ukm-section-title\">Produk Pilihan Terbaru</h2>\n<p class=\"ukm-section-subtitle\">Daftar produk sembako dan kebutuhan harian dengan harga terbaik</p>\n\n</div>\n[products limit=\"8\" columns=\"4\" orderby=\"date\" order=\"ASC\"]\n<div class=\"text-center mt-30\"><a class=\"ukm-btn ukm-btn-secondary\" href=\"/shop/\">Lihat Semua Produk di Katalog Toko →</a></div>\n</div>\n<!-- Section Nilai Unggulan Toko -->\n<div class=\"ukm-section ukm-bg-highlight\">\n<div class=\"ukm-section-header\">\n<h2 class=\"ukm-section-title\">Keunggulan Berbelanja di Toko Kami</h2>\n<p class=\"ukm-section-subtitle\">Komitmen kami memberikan layanan dan produk sembako bermutu bagi masyarakat</p>\n\n</div>\n<div class=\"ukm-features-grid\">\n<div class=\"ukm-feature-box\">\n<h4>Harga Bersaing</h4>\nHarga langsung tangan pertama, cocok untuk belanja keluarga maupun pasokan warung.\n\n</div>\n<div class=\"ukm-feature-box\">\n<h4>Kualitas Terjamin</h4>\nBeras pulen pilihan, minyak goreng jernih, dan produk resmi berstandar BPOM.\n\n</div>\n<div class=\"ukm-feature-box\">\n<h4>Stok Selalu Tersedia</h4>\nPasokan barang selalu diperbarui setiap hari untuk menjamin ketersediaan pesanan Anda.\n\n</div>\n<div class=\"ukm-feature-box\">\n<h4>Pelayanan Ramah</h4>\nProses pemesanan cepat dengan konfirmasi langsung melalui WhatsApp customer service.\n\n</div>\n</div>\n</div>\n<!-- Section Mitra &amp; Klien -->\n<div class=\"ukm-section\">\n<div class=\"ukm-section-header\">\n<h2 class=\"ukm-section-title\">Mitra &amp; Klien Terpercaya</h2>\n<p class=\"ukm-section-subtitle\">Telah dipercaya oleh berbagai pelaku usaha kuliner dan toko kelontong sekitar</p>\n\n</div>\n<div class=\"ukm-client-grid\">\n<div class=\"ukm-client-box\">\n<div class=\"ukm-client-badge\">Mitra Toko Kelontong</div>\n<h3>Toko Sembako Bu RT</h3>\n<p class=\"ukm-client-loc\">Pasar Minggu, Jakarta Selatan</p>\n<p class=\"ukm-client-quote\">\"Pasokan beras dan minyak goreng selalu tepat waktu, kualitas stabil, dan harga sangat menguntungkan untuk dijual kembali.\"</p>\n\n</div>\n<div class=\"ukm-client-box\">\n<div class=\"ukm-client-badge\">Mitra Kuliner</div>\n<h3>Warung Makan Pak Slamet</h3>\n<p class=\"ukm-client-loc\">Tebet, Jakarta Selatan</p>\n<p class=\"ukm-client-quote\">\"Sangat membantu kebutuhan harian dapur rumah makan kami. Beras selalu pulen dan minyak goreng berkualitas baik.\"</p>\n\n</div>\n</div>\n</div>\n<!-- Section Call to Action -->\n<div class=\"ukm-cta-banner\">\n<h2>Siap Memenuhi Kebutuhan Sembako Anda?</h2>\nHubungi admin kami untuk konsultasi pesanan partai besar, paket sembako, atau kebutuhan pasokan rutin.\n\n<a class=\"ukm-btn ukm-btn-white\" href=\"/shop/\">Kunjungi Katalog Produk Sekarang</a>\n\n</div>','Beranda','','publish','closed','closed','','beranda','','','2026-10-05 09:30:50','2026-10-05 09:30:50','',0,'http://localhost:8080/?page_id=4',0,'page','',0),(5,0,'2026-09-30 09:18:40','2026-09-30 09:18:40','','Tentang Kami','','publish','closed','closed','','tentang-kami','','','2026-09-30 09:18:40','2026-09-30 09:18:40','',0,'http://localhost:8080/?page_id=5',0,'page','',0),(6,0,'2026-09-30 09:18:47','2026-09-30 09:18:47','Menyimpan beras dengan benar sangat penting...','Tips Menyimpan Beras Agar Bebas Kutu','','publish','open','open','','tips-menyimpan-beras-agar-bebas-kutu','','','2026-09-30 09:18:47','2026-09-30 09:18:47','',0,'http://localhost:8080/?p=6',0,'post','',0),(7,0,'2026-09-30 09:18:48','2026-09-30 09:18:48','Banyak yang bingung memilih minyak goreng...','Perbedaan Minyak Kelapa dan Sawit','','publish','open','open','','perbedaan-minyak-kelapa-dan-sawit','','','2026-09-30 09:18:48','2026-09-30 09:18:48','',0,'http://localhost:8080/?p=7',0,'post','',0),(8,0,'2026-09-30 09:18:48','2026-09-30 09:18:48','Dapatkan diskon menarik untuk pembelian sembako grosir...','Promo Sembako Akhir Bulan','','publish','open','open','','promo-sembako-akhir-bulan','','','2026-09-30 09:18:48','2026-09-30 09:18:48','',0,'http://localhost:8080/?p=8',0,'post','',0),(9,1,'2026-09-30 10:02:38','2026-09-30 10:02:38','','Beras','','publish','closed','closed','','beras','','','2026-10-05 04:50:11','2026-10-05 04:50:11','',0,'http://localhost:8080/produk/beras-5kg/',0,'product','',0),(10,1,'2026-09-30 10:02:38','2026-09-30 10:02:38','','Minyak Goreng','','publish','closed','closed','','minyak-goreng','','','2026-10-05 04:50:12','2026-10-05 04:50:12','',0,'http://localhost:8080/produk/minyak-1l/',0,'product','',0),(11,1,'2026-09-30 10:02:38','2026-09-30 10:02:38','','Sabun','','publish','closed','closed','','sabun','','','2026-10-05 04:50:12','2026-10-05 04:50:12','',0,'http://localhost:8080/produk/sabun/',0,'product','',0),(12,0,'2026-10-03 16:01:20','2026-10-03 16:01:20','','woocommerce-placeholder','','inherit','open','closed','','woocommerce-placeholder','','','2026-10-03 16:01:20','2026-10-03 16:01:20','',0,'http://localhost:8080/wp-content/uploads/2026/10/woocommerce-placeholder.webp',0,'attachment','image/webp',0),(13,1,'2026-10-03 16:01:21','2026-10-03 16:01:21','','Shop','','publish','closed','closed','','shop','','','2026-10-03 16:01:21','2026-10-03 16:01:21','',0,'http://localhost:8080/shop/',0,'page','',0),(14,1,'2026-10-03 16:01:21','2026-10-03 16:01:21','[woocommerce_cart]','Cart','','publish','closed','closed','','cart','','','2026-10-09 02:47:09','2026-10-09 02:47:09','',0,'http://localhost:8080/cart/',0,'page','',0),(15,1,'2026-10-03 16:01:21','2026-10-03 16:01:21','[woocommerce_checkout]','Checkout','','publish','closed','closed','','checkout','','','2026-10-09 02:47:10','2026-10-09 02:47:10','',0,'http://localhost:8080/checkout/',0,'page','',0),(16,1,'2026-10-03 16:01:21','2026-10-03 16:01:21','<!-- wp:shortcode -->[woocommerce_my_account]<!-- /wp:shortcode -->','My account','','publish','closed','closed','','my-account','','','2026-10-03 16:01:21','2026-10-03 16:01:21','',0,'http://localhost:8080/my-account/',0,'page','',0),(17,1,'2026-10-03 16:01:21','0000-00-00 00:00:00','<!-- wp:paragraph -->\n<p><b>This is a sample page.</b></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Overview</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Our refund and returns policy lasts 30 days. If 30 days have passed since your purchase, we can’t offer you a full refund or exchange.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>To be eligible for a return, your item must be unused and in the same condition that you received it. It must also be in the original packaging.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Several types of goods are exempt from being returned. Perishable goods such as food, flowers, newspapers or magazines cannot be returned. We also do not accept products that are intimate or sanitary goods, hazardous materials, or flammable liquids or gases.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Additional non-returnable items:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n<li>Gift cards</li>\n<li>Downloadable software products</li>\n<li>Some health and personal care items</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>To complete your return, we require a receipt or proof of purchase.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Please do not send your purchase back to the manufacturer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>There are certain situations where only partial refunds are granted:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n<li>Book with obvious signs of use</li>\n<li>CD, DVD, VHS tape, software, video game, cassette tape, or vinyl record that has been opened.</li>\n<li>Any item not in its original condition, is damaged or missing parts for reasons not due to our error.</li>\n<li>Any item that is returned more than 30 days after delivery</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Refunds</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Once your return is received and inspected, we will send you an email to notify you that we have received your returned item. We will also notify you of the approval or rejection of your refund.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you are approved, then your refund will be processed, and a credit will automatically be applied to your credit card or original method of payment, within a certain amount of days.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Late or missing refunds</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you haven’t received a refund yet, first check your bank account again.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Then contact your credit card company, it may take some time before your refund is officially posted.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Next contact your bank. There is often some processing time before a refund is posted.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you’ve done all of this and you still have not received your refund yet, please contact us at {email address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Sale items</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Only regular priced items may be refunded. Sale items cannot be refunded.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Exchanges</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We only replace items if they are defective or damaged. If you need to exchange it for the same item, send us an email at {email address} and send your item to: {physical address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Gifts</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If the item was marked as a gift when purchased and shipped directly to you, you’ll receive a gift credit for the value of your return. Once the returned item is received, a gift certificate will be mailed to you.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If the item wasn’t marked as a gift when purchased, or the gift giver had the order shipped to themselves to give to you later, we will send a refund to the gift giver and they will find out about your return.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Shipping returns</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>To return your product, you should mail your product to: {physical address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You will be responsible for paying for your own shipping costs for returning your item. Shipping costs are non-refundable. If you receive a refund, the cost of return shipping will be deducted from your refund.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Depending on where you live, the time it may take for your exchanged product to reach you may vary.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you are returning more expensive items, you may consider using a trackable shipping service or purchasing shipping insurance. We don’t guarantee that we will receive your returned item.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"